function ColumnGrouping({
  caption = "{{caption}}",
  accent = "{{accent}}",
  groupLabel = "{{groupLabel}}",
  showSubheaders = {{showSubheaders}},
  collapsedGroup = {{collapsedGroup}},
}) {
  const rows = [
    ["A. Whitfield", "14 Elm Rd", "Leeds", "Courier", "£64.00"],
    ["R. Okafor", "9 Quay St", "Bristol", "Post", "£128.50"],
    ["M. Iqbal", "2 Mill Ln", "Leicester", "Courier", "£22.00"],
    ["S. Novak", "51 Bank St", "York", "Post", "£40.00"],
  ];
  const cell = { padding: "8px 12px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  const subCell = collapsedGroup ? { ...cell, maxWidth: 44, overflow: "hidden", textOverflow: "ellipsis" } : cell;
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>{caption}</caption>
          <thead>
            <tr>
              <th scope="col" rowSpan={2} style={cell}>Customer</th>
              <th scope="colgroup" colSpan={2} style={{ ...cell, background: accent, color: "#FAF7F2", textAlign: "center" }}>{groupLabel}</th>
              <th scope="col" rowSpan={2} style={cell}>Method</th>
              <th scope="col" rowSpan={2} style={cell}>Total</th>
            </tr>
            {showSubheaders && (
              <tr>
                <th scope="col" style={{ ...cell, background: "#24143012", fontSize: 12 }}>Address</th>
                <th scope="col" style={{ ...cell, background: "#24143012", fontSize: 12 }}>City</th>
              </tr>
            )}
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r[0]}>
                <td style={cell}>{r[0]}</td>
                <td style={subCell}>{r[1]}</td>
                <td style={subCell}>{r[2]}</td>
                <td style={cell}>{r[3]}</td>
                <td style={cell}>{r[4]}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
